correctedCode:
public class PositivePrinter {
    public static void main(String[] args) {
        int[] numbers = {3, -1, 5, -2, 8};
        for (int n : numbers) {
            if (n < 0) {
                continue;
            }
            System.out.println(n);
        }
    }
}
